import React, { useEffect, useState } from "react";
import { Container, Card, Badge } from "react-bootstrap";

function Maps() {
  // ข้อมูลพิกัดและจำนวนคน (อ้างอิงจากที่คุณให้มา)
  const [markers, setMarkers] = useState([
    { name: "คณะศิลปศาสตร์", latitude: 19.029554, longitude: 99.895707, count: 15 },
    { name: "คณะวิทยาศาสตร์", latitude: 19.030488, longitude: 99.897405, count: 32 },
    { name: "คณะวิศวกรรมศาสตร์", latitude: 19.030734, longitude: 99.900750, count: 8 },
    { name: "อาคารเรียนรวม (PKY)", latitude: 19.025677, longitude: 99.894938, count: 50 },
  ]);

  useEffect(() => {
    // --- เริ่มต้นโหลด Leaflet (แบบไม่ใช้ Library ผ่าน npm) ---
    // 1. โหลด CSS ของ Leaflet
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(link);

    // 2. โหลด JavaScript ของ Leaflet
    const script = document.createElement("script");
    script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    script.async = true;
    script.onload = () => {
      const L = window.L;

      // ล้างข้อมูลแผนที่เดิมถ้ามีการ Re-render
      const container = L.DomUtil.get('map-container');
      if (container != null) {
        container._leaflet_id = null;
      }

      // สร้างแผนที่ (SetView ไปที่จุดกลางของกลุ่มอาคาร)
      const map = L.map("map-container").setView([19.029, 99.897], 15);

      // ใช้แผนที่จาก OpenStreetMap
      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
        attribution: '&copy; OpenStreetMap contributors',
      }).addTo(map);

      // วางมาร์กเกอร์ตามพิกัด
      markers.forEach((point) => {
        // สร้าง Icon ที่แสดงตัวเลขจำนวนคน (Custom DivIcon)
        // วิธีนี้จะทำให้ตัวเลขเกาะติดกับพิกัดแผนที่ ไม่ลอยเวลาเลื่อน map
        const numberIcon = L.divIcon({
          className: 'custom-number-icon',
          html: `
            <div style="
              background-color: ${point.count > 20 ? '#dc3545' : '#28a745'};
              color: white;
              border-radius: 50%;
              width: 40px;
              height: 40px;
              display: flex;
              align-items: center;
              justify-content: center;
              font-weight: bold;
              font-size: 16px;
              border: 3px solid white;
              box-shadow: 0 3px 6px rgba(0,0,0,0.3);
            ">
              ${point.count}
            </div>
          `,
          iconSize: [40, 40],
          iconAnchor: [20, 20], // จุดยึดอยู่ตรงกลาง (ครึ่งหนึ่งของ size) เพื่อให้ตรงพิกัดเป๊ะ
          popupAnchor: [0, -20]
        });

        L.marker([point.latitude, point.longitude], { icon: numberIcon })
          .addTo(map)
          .bindPopup(`
            <div style="font-family: 'Kanit', sans-serif;">
              <strong>${point.name}</strong><br/>
              จำนวนคน: <span style="color: blue; font-size: 1.2em;">${point.count}</span> คน
            </div>
          `);
      });
    };
    document.body.appendChild(script);
  }, [markers]);

  return (
    <Container fluid>
      <Card>
        <Card.Header>
          <Card.Title as="h4">📍 แผนที่แสดงความหนาแน่น (Bus Stops)</Card.Title>
          <p className="card-category">แสดงพิกัดและจำนวนคน ณ จุดรับส่ง</p>
        </Card.Header>

        <Card.Body>
          {/* ส่วนแผนที่ - เปลี่ยนจาก iframe เป็น div สำหรับ Leaflet */}
          <div
            id="map-container"
            style={{
              height: "500px",
              width: "100%",
              borderRadius: "10px",
              marginBottom: "20px",
              border: "1px solid #ddd"
            }}
          ></div>

          {/* รายละเอียดข้อมูลจำนวนคนด้านล่าง */}
          <h5>📊 รายละเอียดข้อมูลในแต่ละจุด</h5>
          <div className="mt-3">
            {markers.map((stop, index) => (
              <div key={index} className="d-flex justify-content-between align-items-center mb-3 p-2 border-bottom">
                <div>
                  <strong>{stop.name}</strong><br/>
                  <small className="text-muted">Lat: {stop.latitude}, Lng: {stop.longitude}</small>
                </div>
                <div className="text-end">
                  <Badge bg="primary" pill style={{ fontSize: '1rem', padding: '10px 15px' }}>
                    {stop.count} คน
                  </Badge>
                </div>
              </div>
            ))}
          </div>

          <p style={{ color: "green" }} className="mt-3">
            ✔ ดึงข้อมูลพิกัดและแสดงมาร์กเกอร์เรียบร้อยแล้ว
          </p>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default Maps;
